      const left = 2 * i + 1;
      const right = left + 1;
      let pick = i;
      if (left < heap.length && heap[left] < heap[pick]) pick = left;
      if (right < heap.length && heap[right] < heap[pick]) pick = right;
      if (pick === i) return top;
