function minimumDifference(nums) {
  const n = nums.length / 3;
  const kept = [];
  let best = Infinity;
  const walk = (index, removed) => {
    if (index === nums.length) {
      let diff = 0;
      for (let j = 0; j < kept.length; j++) diff += j < n ? kept[j] : -kept[j];
      best = Math.min(best, diff);
      return;
    }
    if (removed < n) walk(index + 1, removed + 1);
    if (kept.length < 2 * n) {
      kept.push(nums[index]);
      walk(index + 1, removed);
      kept.pop();
    }
  };
  walk(0, 0);
  return best;
}

