function generate(rand, size) {
  const n = size === 'large' ? 666 : 1 + Math.floor(rand() * 4);
  const top = rand() < 0.3 ? 5 : 100000;
  const nums = Array.from({ length: 3 * n }, () => 1 + Math.floor(rand() * top));
  const style = rand();
  if (style < 0.15) nums.sort((a, b) => a - b);
  else if (style < 0.3) nums.sort((a, b) => b - a);
  return [nums];
}
